    def longest_unique_from(start):
        seen = set()
        end = start
        while end < len(text) and text[end] not in seen:
            seen.add(text[end])
            end += 1
        return end - start

    best = 0
    for i in range(len(text)):
        length = longest_unique_from(i)
        if length > best:
            best = length
    return best

