        return s[i]

    def length(s):
        return len(s)

    def max(a, b):
        return a if a > b else b

    def scan(s):
        n = length(s)
        if n == 0:
            return 0
        last = {}
        start = 0
        best = 0
        i = 0
        while i < n:
            c = char_at(s, i)
            if c in last and last[c] >= start:
