    def match(i, j):
        if j == len(pattern):
            return i == len(text)
        if pattern[j] == '*':
            while j + 1 < len(pattern) and pattern[j + 1] == '*':
                j += 1
            if j + 1 == len(pattern):
                return True
            for k in range(i, len(text) + 1):
