def topological_order(graph):
    def build_nodes(graph):
        nodes = set()
        for node in graph:
            nodes.add(node)
            for neighbor in graph[node]:
                nodes.add(neighbor)
        return nodes

    def build_adjacency(graph, nodes):
        adjacency = {}
        for node in nodes:
            adjacency[node] = set()
        for node in graph:
            for neighbor in graph[node]:
                adjacency[node].add(neighbor)
        return adjacency

    def build_indegrees(adjacency):
        indegree = {}
        for node in adjacency:
            indegree[node] = 0
        for node in adjacency:
            for neighbor in adjacency[node]:
                indegree[neighbor] += 1
        return indegree

    def smallest_available(indegree, available):
        result = None
        for node in available:
            if indegree[node] == 0:
                if result is None or node < result:
                    result = node
        return result

    nodes = build_nodes(graph)
    adjacency = build_adjacency(graph, nodes)
    indegree = build_indegrees(adjacency)
    available = set(nodes)
    order = []

    while available:
        node = smallest_available(indegree, available)
        if node is None:
            raise ValueError("directed cycle")
        order.append(node)
        available.remove(node)
        for neighbor in adjacency[node]:
            indegree[neighbor] -= 1

    return order

