def lru_simulate(capacity, operations):
    def find_index(keys, key):
        for i in range(len(keys)):
            if keys[i] == key:
                return i
        return -1

    def remove_at(items, index):
        return items[:index] + items[index + 1:]

    def append_item(items, item):
        return items + [item]

    def move_to_end(keys, values, key):
        index = find_index(keys, key)
        if index == -1:
            return keys, values
        value = values[index]
        keys = remove_at(keys, index)
        values = remove_at(values, index)
        keys = append_item(keys, key)
        values = append_item(values, value)
        return keys, values

    def put_item(keys, values, key, value):
        index = find_index(keys, key)
        if index != -1:
            keys = remove_at(keys, index)
            values = remove_at(values, index)
        keys = append_item(keys, key)
        values = append_item(values, value)
        while len(keys) > capacity:
            keys = keys[1:]
            values = values[1:]
        return keys, values

    def get_item(keys, values, key):
        index = find_index(keys, key)
        if index == -1:
            return None, keys, values
        value = values[index]
        keys, values = move_to_end(keys, values, key)
        return value, keys, values

    keys = []
    values = []
    get_results = []

    for operation in operations:
        if operation[0] == 'put':
            keys, values = put_item(keys, values, operation[1], operation[2])
        else:
            result, keys, values = get_item(keys, values, operation[1])
            get_results = append_item(get_results, result)

    return [get_results, keys]

